export const getGetDailyActivityUrl = (params?: GetDailyActivityParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/alerts/daily?${stringifiedParams}` : `/api/alerts/daily`
}

/**
 * @summary Daily activity feed — pages published and pages optimized, grouped by day on the client
 */
